# Just load and save grids from the environment/session
import os, re, json, glob

def load_grids():
    """Load all demo pairs from session"""
    session_dir = os.environ.get('RLM_SESSION_DIR')
    if not session_dir:
        return {}

    parent = os.path.dirname(session_dir)
    sessions_file = f'{parent}/sessions/{os.path.basename(session_dir)}.jsonl'

    if not os.path.exists(sessions_file):
        return {}

    with open(sessions_file) as f:
        content = f.read()

    grids = {}
    # Pattern matches: "(Demo pair N input)" or "(Demo pair N output)" or "Test input (NxM)"
    for line in content.split('\n'):
        if not line.strip():
            continue
        match = re.match(r'\(Demo pair (\d+) input\)', line.strip())
        if match:
            pair_num = int(match.group(1))
            grids[Pair_key(f'Demo pair {pair_num} ')] = "input"
        match = re.match(r'\(Demo pair (\d+) output\)', line.strip())
        if match:
            pair_num = int(match.group(1))
            grids[Pair_key(f'Demo pair {pair_num} ')] = "output"

    return grids

def Pair_key(k):
    return (k, len(k))

print("Loaded grid keys:", sorted(load_grids().keys())[:10])

